% All
data_All = [data_D1; data_D2; data_D3]; 

datasets_data = {data_D1, data_D2, data_D3, data_All};
panel_titles = {'Dataset_1', 'Dataset_2', 'Dataset_3', '(all)'};
methods = {'VoD-Sampler', 'SO-SDC', 'MO-SDC', 'STRaP', 'BehAVExplor', 'Random'};
num_methods = length(methods);
font_name = 'Arial';
colors_all = [
    0.5569, 0.7294, 0.2588;  
    0.7176, 0.4549, 1.0000; 
    0.9843, 0.5020, 0.4471; 
    0.3451, 0.7686, 0.8627;  
    0.9529, 0.7647, 0.2000;  
    0.6000, 0.6000, 0.6000   
];

fig = figure('Position', [100, 100, 750, 400], 'Color', 'w');

left_margin = 0.08; 
right_margin = 0.02;
bottom_margin = 0.25; 
top_margin = 0.12;    
gap = 0.015;  

panel_width = (1 - left_margin - right_margin - 3*gap) / 4;
panel_height = 1 - bottom_margin - top_margin;


global_min = min(data_All(:));
global_max = max(data_All(:));
y_margin = (global_max - global_min) * 0.1;
y_limits = [global_min - y_margin, global_max + y_margin];

for p = 1:4
    pos_x = left_margin + (p-1)*(panel_width + gap);
    ax = axes('Position', [pos_x, bottom_margin, panel_width, panel_height]);
    hold(ax, 'on');
    set(ax, 'Color', [0.92, 0.92, 0.92], ...    
            'XGrid', 'on', 'YGrid', 'on', ...
            'GridColor', [1, 1, 1], ...         
            'GridAlpha', 1, ...                 
            'LineWidth', 1.0, ...
            'XColor', [0.3, 0.3, 0.3], 'YColor', [0.3, 0.3, 0.3], ...
            'TickDir', 'out');
    annotation('textbox', [pos_x, bottom_margin + panel_height, panel_width, 0.06], ...
               'String', panel_titles{p}, ...
               'BackgroundColor', [0.85, 0.85, 0.85], ... 
               'EdgeColor', [0.85, 0.85, 0.85], ...
               'HorizontalAlignment', 'center', ...
               'VerticalAlignment', 'middle', ...
               'FontWeight', 'bold', 'FontSize', 14, 'FontName', font_name);
    current_data = datasets_data{p};
    box_width = 0.4; 

    for i = 1:num_methods
        y = current_data(:, i);
        
        q1 = prctile(y, 25);
        q3 = prctile(y, 75);
        med = median(y);
        mean_val = mean(y);
        iqr_val = q3 - q1;
        
        lower_bound = q1 - 1.5 * iqr_val;
        upper_bound = q3 + 1.5 * iqr_val;
        
        whisker_low = min(y(y >= lower_bound));
        whisker_high = max(y(y <= upper_bound));
        if isempty(whisker_low), whisker_low = q1; end
        if isempty(whisker_high), whisker_high = q3; end
        
        outliers = y(y < lower_bound | y > upper_bound);
        if p < 4
            face_color = 'w';
        else
            face_color = colors_all(i, :);
        end
        plot(ax, [i, i], [whisker_low, q1], 'k-', 'LineWidth', 1.2);
        plot(ax, [i, i], [q3, whisker_high], 'k-', 'LineWidth', 1.2);
        patch(ax, [i-box_width, i+box_width, i+box_width, i-box_width], ...
                  [q1, q1, q3, q3], face_color, 'EdgeColor', 'k', 'LineWidth', 1.2);
        plot(ax, [i-box_width, i+box_width], [med, med], 'k-', 'LineWidth', 3.0);
        plot(ax, i, mean_val, 'd', 'MarkerEdgeColor', 'k', ...
             'MarkerFaceColor', 'w', 'MarkerSize', 6, 'LineWidth', 1.2);
        if ~isempty(outliers)
            plot(ax, i * ones(size(outliers)), outliers, 'ko', ...
                 'MarkerFaceColor', 'k', 'MarkerSize', 4);
        end
    end
    xlim(ax, [0.5, num_methods+0.5]);
    ylim(ax, y_limits);
    
    set(ax, 'XTick', 1:num_methods, 'XTickLabel', methods, ...
            'FontSize', 13, 'FontWeight', 'bold', 'FontName', font_name);
    xtickangle(ax, 90);
    if p == 1
        ylabel(ax, 'CDW-APFD Score', 'FontSize', 15, 'FontWeight', 'bold', 'FontName', font_name);
    else
        set(ax, 'YTickLabel', []); 
    end
    
    box(ax, 'on');
    set(ax, 'Layer', 'top');
end

